export interface Parcel {
  weightGrams: number;
  destination: string;
}
export interface CarrierRate {
  service: string;
  amountCents: number;
  days: number;
}
export interface Carrier {
  id: string;
  quote(parcel: Parcel): Promise<readonly CarrierRate[]>;
}
export interface DeliveryOption extends CarrierRate {
  carrierId: string;
}
export interface QuoteResult {
  options: DeliveryOption[];
}
export interface CheckoutDelivery {
  options: DeliveryOption[];
  recommended: DeliveryOption | null;
  message: string;
}
import type { Carrier, DeliveryOption, Parcel, QuoteResult } from './model.js';
import { compareOptions, copyParcel, isUsableRate, validateParcel } from './policy.js';

export class DeliveryQuotes {
  constructor(private readonly carriers: readonly Carrier[]) {}

  async collect(parcel: Parcel): Promise<QuoteResult> {
    validateParcel(parcel);
    const batches = await Promise.all(this.carriers.map(async carrier => {
      const rates = await carrier.quote(copyParcel(parcel));
      const options: DeliveryOption[] = [];
      for (const rate of rates) {
        if (isUsableRate(rate)) {
          options.push({
            carrierId: carrier.id,
            service: rate.service,
            amountCents: rate.amountCents,
            days: rate.days,
          });
        }
      }
      return options;
    }));
    const options = batches.flat();
    options.sort(compareOptions);
    return { options };
  }
}
import type { CheckoutDelivery, DeliveryOption, Parcel } from './model.js';
import { DeliveryQuotes } from './quotes.js';
import { describeOption } from './policy.js';

export interface DeliveryRequest {
  parcel: Parcel;
  maximumDays?: number;
}

export class Checkout {
  constructor(private readonly quotes: DeliveryQuotes) {}

  async delivery(request: DeliveryRequest): Promise<CheckoutDelivery> {
    if (request.maximumDays !== undefined
      && (!Number.isSafeInteger(request.maximumDays) || request.maximumDays < 1)) {
      throw new RangeError('Maximum days must be a positive integer');
    }
    const result = await this.quotes.collect(request.parcel);
    const options: DeliveryOption[] = result.options.filter(option =>
      request.maximumDays === undefined || option.days <= request.maximumDays);
    const recommended = options[0] ?? null;
    return {
      options,
      recommended,
      message: recommended ? describeOption(recommended) : 'No delivery options',
    };
  }
}
import type { CarrierRate, DeliveryOption, Parcel } from './model.js';

export function validateParcel(parcel: Parcel): void {
  if (!Number.isSafeInteger(parcel.weightGrams) || parcel.weightGrams <= 0) {
    throw new RangeError('Weight must be a positive integer');
  }
  if (!parcel.destination.trim()) {
    throw new RangeError('Destination is required');
  }
}

// Carrier payloads are untrusted, even when the adapter has static types.
export function isUsableRate(rate: CarrierRate): boolean {
  return typeof rate.service === 'string' && rate.service.trim().length > 0
    && Number.isSafeInteger(rate.amountCents) && rate.amountCents >= 0
    && Number.isSafeInteger(rate.days) && rate.days >= 1;
}

export function compareOptions(a: DeliveryOption, b: DeliveryOption): number {
  return a.amountCents - b.amountCents
    || a.days - b.days
    || a.carrierId.localeCompare(b.carrierId)
    || a.service.localeCompare(b.service);
}

export function copyParcel(parcel: Parcel): Parcel {
  return { weightGrams: parcel.weightGrams, destination: parcel.destination };
}

export function describeOption(option: DeliveryOption): string {
  const unit = option.days === 1 ? 'day' : 'days';
  return `${option.carrierId} ${option.service}: ${option.days} ${unit}`;
}
